 async function findPeople(){if(!user){setAuthOpen(true);return}if(peopleTerm.trim().length<2)return notify("Enter at least 2 characters.");const term=peopleTerm.trim();const r=await supabase.from("profiles").select("id,username,display_name,bio").ilike("username","%"+term+"%").neq("id",user.id).limit(50);if(r.error)return notify("Search failed: "+r.error.message);const rows=r.data||[];if(!rows.length){setPeople([]);notify("No members found for that username.");return}const ids=rows.map(x=>x.id);const presence=await supabase.from("user_presence").select("user_id,is_online,last_seen_at").in("user_id",ids);const now=Date.now();const status:Record<string,boolean>={};(presence.data||[]).forEach(x=>status[x.user_id]=!!x.is_online&&!!x.last_seen_at&&(now-new Date(x.last_seen_at).getTime()<90000));setPeople(rows.map(x=>({...x,isOnline:!!status[x.id]})).sort((a,b)=>Number(b.isOnline)-Number(a.isOnline)));}
 async function addFriend(id:string){if(!user){setAuthOpen(true);return}if(id===user.id)return notify("You cannot add your own account.");const existing=await supabase.from("friend_requests").select("id,status,sender_id,receiver_id").or("and(sender_id.eq."+user.id+",receiver_id.eq."+id+"),and(sender_id.eq."+id+",receiver_id.eq."+user.id+")").maybeSingle();if(existing.error)return notify("Could not check friend request: "+existing.error.message);if(existing.data){if(existing.data.status==="accepted"){await loadSocial();return notify("You are already friends. Refresh your messages.")}if(existing.data.status==="pending")return notify(existing.data.sender_id===user.id?"Friend request already sent. Ask them to accept it.":"They already sent you a request. Check Incoming requests.");const del=await supabase.from("friend_requests").delete().eq("id",existing.data.id);if(del.error)return notify("Could not retry request: "+del.error.message)}const r=await supabase.from("friend_requests").insert({sender_id:user.id,receiver_id:id,status:"pending"});if(r.error)return notify("Request failed: "+r.error.message);notify("Friend request sent.");await loadSocial()}
